73	
74	@RestController
75	@CrossOrigin(exposedHeaders = "errors, content-type")
76	@RequestMapping("/api")
77	public class OwnerRestControllerV1 implements OwnersApi {
78	
79	    /**
80	     * Dedicated audit logger. On a successful owner create an audit line carrying the owner id,
81	     * the {@code customerCode} and the {@code registrationDate} is emitted to this named logger.
82	     */
83	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
84	
85	    private final ClinicService clinicService;
86	
87	    private final OwnerMapper ownerMapper;
88	
89	    private final PetMapper petMapper;
90	
91	    private final VisitMapper visitMapper;
92	
93	    public OwnerRestControllerV1(ClinicService clinicService,
94	                                 OwnerMapper ownerMapper,
95	                                 PetMapper petMapper,
96	                                 VisitMapper visitMapper) {
97	        this.clinicService = clinicService;
98	        this.ownerMapper = ownerMapper;
99	        this.petMapper = petMapper;
100	        this.visitMapper = visitMapper;
101	    }
102	
103	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
104	    @Override
105	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
106	        Collection<Owner> owners;
107	        if (lastName != null) {
108	            owners = this.clinicService.findOwnerByLastName(lastName);
109	        } else {
110	            owners = this.clinicService.findAllOwners();
111	        }
112	        if (owners.isEmpty()) {
113	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
114	        }
115	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
116	    }
117	
118	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
119	    @Override
120	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
121	        Owner owner = this.clinicService.findOwnerById(ownerId);
122	        if (owner == null) {
123	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
124	        }
125	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
126	    }
127	
128	    /**
129	     * Rejects an owner payload that is missing or blank in any of the required fields
130	     * (firstName, lastName, address, city, telephone). Bean Validation on the request body
131	     * already rejects {@code null} values and empty strings, but treats a whitespace-only
132	     * value as present; this guard closes that gap so a blank in any required field is
133	     * reported. The thrown exception is translated to a 400 whose {@code errors} array lists
134	     * the name of each offending field.
135	     */
136	    private void rejectMissingOrBlankFields(OwnerFieldsDto ownerFieldsDto, String normalizedAddress) {
137	        List<String> missing = new ArrayList<>();
138	        if (isBlank(ownerFieldsDto.getFirstName())) {
139	            missing.add("firstName");
140	        }
141	        if (isBlank(ownerFieldsDto.getLastName())) {
142	            missing.add("lastName");
143	        }
144	        if (isBlank(normalizedAddress)) {
145	            missing.add("address");
146	        }
147	        if (isBlank(ownerFieldsDto.getCity())) {
148	            missing.add("city");
149	        }
150	        if (isBlank(ownerFieldsDto.getTelephone())) {
151	            missing.add("telephone");
152	        }
153	        if (!missing.isEmpty()) {
154	            throw new MissingOwnerFieldsException(missing);
155	        }
156	    }
157	
158	    private static boolean isBlank(String value) {
159	        return value == null || value.isBlank();
160	    }
161	
162	    /**
163	     * Matches a well-formed E.164 telephone: a leading '+' followed by 8 to 15 digits.
164	     */
165	    private static final Pattern E164_PATTERN = Pattern.compile("\\+\\d{8,15}");
166	
167	    /**
168	     * Required national-number length per country calling code. When the normalized E.164 number
169	     * begins with one of these codes, the digits that follow must number exactly the mapped value:
170	     * '+61' (Australia) requires 9 national digits and '+1' (NANP) requires 10. Codes absent from
171	     * this map carry no per-country length rule beyond the generic E.164 8-to-15-digit bound.
172	     */
173	    private static final Map<String, Integer> NATIONAL_NUMBER_LENGTHS = Map.of(
174	        "+61", 9,
175	        "+1", 10);
176	
177	    /**
178	     * Normalizes an owner's telephone on create into E.164 form. Spaces, dashes and brackets are
179	     * stripped. When a leading '+' (with its country code) is present it is kept as-is; otherwise
180	     * the country code '+61' is assumed and a single leading '0' is dropped from the national
181	     * digits. The result must be a '+' followed by 8 to 15 digits, so e.g. '0412 345 678' is
182	     * stored as '+61412345678'. When the country code has a known national-number length ('+61'
183	     * requires 9 national digits, '+1' requires 10) the national digits must match it exactly. A
184	     * value that cannot form a valid E.164 number, or whose national length is wrong for its
185	     * country, is rejected via {@link InvalidTelephoneException}, which the exception handler
186	     * translates to a 400.
187	     */
188	    private static String normalizeTelephone(String telephone) {
189	        String cleaned = telephone == null ? "" : telephone.replaceAll("[\\s\\-()\\[\\]]", "");
190	        String e164;
191	        if (cleaned.startsWith("+")) {
192	            e164 = cleaned;
193	        } else {
194	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
195	            e164 = "+61" + national;
196	        }
197	        if (!E164_PATTERN.matcher(e164).matches()) {
198	            throw new InvalidTelephoneException(telephone);
199	        }
200	        for (Map.Entry<String, Integer> rule : NATIONAL_NUMBER_LENGTHS.entrySet()) {
201	            String code = rule.getKey();
202	            if (e164.startsWith(code)) {
203	                int nationalLength = e164.length() - code.length();
204	                if (nationalLength != rule.getValue()) {
205	                    throw new InvalidTelephoneException(telephone);
206	                }
207	                break;
208	            }
209	        }
210	        return e164;
211	    }
212	
213	    /**
214	     * Matches a well-formed postcode: exactly four digits.
215	     */
216	    private static final Pattern POSTCODE_PATTERN = Pattern.compile("\\d{4}");
217	
218	    /**
219	     * The canonical region for each city that has one. A city absent from this table has no known
220	     * region and so accepts any 4-digit postcode. This is the same fixed city-to-region table used
221	     * to derive an owner's locality.
222	     */
223	    private static final Map<String, String> CITY_REGION = Map.of(
224	        "Sydney", "NSW",
225	        "Melbourne", "VIC",
226	        "Brisbane", "QLD");
227	
228	    /**
229	     * The inclusive 4-digit postcode range for each region, as {@code {low, high}}: NSW 2000-2099,
230	     * VIC 3000-3099, QLD 4000-4099.
231	     */
232	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
233	        "NSW", new int[] {2000, 2099},
234	        "VIC", new int[] {3000, 3099},
235	        "QLD", new int[] {4000, 4099});
236	
237	    /**
238	     * Validates an owner's optional postcode. A {@code null} postcode is left as-is (the field is
239	     * optional). When present it must be exactly four digits; and when the owner's city maps to a
240	     * known region it must fall within that region's inclusive postcode range (NSW 2000-2099, VIC
241	     * 3000-3099, QLD 4000-4099). A city with no known region accepts any 4-digit postcode. An
242	     * invalid or out-of-range value is rejected via {@link InvalidPostcodeException}, which the
243	     * exception handler translates to a 400.
244	     */
245	    private static void validatePostcode(String city, String postcode) {
246	        if (postcode == null) {
247	            return;
248	        }
249	        if (!POSTCODE_PATTERN.matcher(postcode).matches()) {
250	            throw new InvalidPostcodeException(postcode);
251	        }
252	        String region = CITY_REGION.get(city);
253	        if (region == null) {
254	            return;
255	        }
256	        int[] range = REGION_POSTCODES.get(region);
257	        int value = Integer.parseInt(postcode);
258	        if (value < range[0] || value > range[1]) {
259	            throw new InvalidPostcodeException(postcode);
260	        }
261	    }
262	
263	    /**
264	     * A pragmatic syntactic email check: a non-empty local part, an {@code @}, and a domain that
265	     * carries at least one dot, with no whitespace anywhere. Deliberately permissive — it accepts
266	     * ordinary addresses while rejecting obvious non-addresses such as one lacking an {@code @}.
267	     */
268	    private static final Pattern EMAIL_PATTERN = Pattern.compile("^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$");
269	
270	    /**
271	     * Disposable-email domains that an owner's email may not use. An address whose domain (the part
272	     * after the final {@code @}, compared case-insensitively) is one of these is rejected. Kept as a
273	     * fixed set so the block list is explicit and easy to extend.
274	     */
275	    private static final Set<String> DISPOSABLE_EMAIL_DOMAINS = Set.of(
276	        "mailinator.com",
277	        "tempmail.com",
278	        "guerrillamail.com");
279	
280	    /**
281	     * Normalizes an optional owner email. A {@code null} email is left as-is (the field is
282	     * optional). When present it must be a syntactically valid address whose domain is not on the
283	     * disposable-domain block list; a valid value is lower-cased so it is stored and returned in
284	     * canonical form. An invalid or disposable-domain value is rejected via
285	     * {@link InvalidEmailException}, which the exception handler translates to a 400.
286	     */
287	    private static String normalizeEmail(String email) {
288	        if (email == null) {
289	            return null;
290	        }
291	        if (!EMAIL_PATTERN.matcher(email).matches()) {
292	            throw new InvalidEmailException(email);
293	        }
294	        String normalized = email.toLowerCase(Locale.ROOT);
295	        String domain = normalized.substring(normalized.lastIndexOf('@') + 1);
296	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
297	            throw new InvalidEmailException(email);
298	        }
299	        return normalized;
300	    }
301	
302	    /**
303	     * The single derived identity of an owner, {@code normalizedTelephone + '|' + (email or empty)
304	     * + '|' + householdId}, into which all duplicate detection is consolidated. Two owners are the
305	     * same identity only when this whole key matches: because the normalized telephone is part of
306	     * the key, two members of the same household (same {@code householdId}) with different
307	     * telephones have different identity keys. A {@code null} email contributes an empty middle
308	     * segment. This is the value returned to callers as {@code identityKey}.
309	     */
310	    private static String identityKeyFor(String normalizedTelephone, String normalizedEmail, String householdId) {
311	        return normalizedTelephone + "|" + (normalizedEmail == null ? "" : normalizedEmail) + "|" + householdId;
312	    }
313	
314	    /**
315	     * Rejects a create whose derived identity collides with an existing owner's, reported via one
316	     * of the {@code Duplicate*} exceptions the handler translates to a 409. The former separate
317	     * telephone, email and household checks are now expressed through the components of the single
318	     * identity key:
319	     * <ul>
320	     *   <li>the normalized telephone matches an existing owner's canonical E.164 telephone (an
321	     *       existing value that cannot form a valid E.164 number is skipped rather than colliding);</li>
322	     *   <li>a present, lower-cased email matches an existing owner's lower-cased email (a {@code null}
323	     *       candidate email, being optional, is not compared, and existing owners without an email
324	     *       are skipped);</li>
325	     *   <li>the {@code householdId} matches an existing owner's - unless the caller opted into sharing
326	     *       a household via {@code sharesHousehold}, in which case the household component is not
327	     *       compared.</li>
328	     * </ul>
329	     */
330	    private void rejectDuplicateIdentity(OwnerFieldsDto ownerFieldsDto, String normalizedTelephone,
331	                                         String normalizedEmail, String householdId) {
332	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
333	        for (Owner existing : this.clinicService.findAllOwners()) {
334	            if (existing.isDeleted()) {
335	                continue;
336	            }
337	            String existingTelephone;
338	            try {
339	                existingTelephone = normalizeTelephone(existing.getTelephone());
340	            } catch (InvalidTelephoneException ex) {
341	                existingTelephone = null;
342	            }
343	            if (normalizedTelephone.equals(existingTelephone)) {
344	                throw new DuplicateTelephoneException(normalizedTelephone);
345	            }
346	            if (normalizedEmail != null) {
347	                String existingEmail = existing.getEmail();
348	                if (existingEmail != null && normalizedEmail.equals(existingEmail.toLowerCase(Locale.ROOT))) {
349	                    throw new DuplicateEmailException(normalizedEmail);
350	                }
351	            }
352	            if (!sharesHousehold
353	                && householdId.equals(householdIdFor(existing.getLastName(), existing.getPostcode()))) {
354	                throw new DuplicateHouseholdException(ownerFieldsDto.getLastName(), ownerFieldsDto.getPostcode());
355	            }
356	        }
357	    }
358	
359	    /**
360	     * Collapses a value for household comparison: leading and trailing whitespace is trimmed, any
361	     * internal run of whitespace is reduced to a single space, and the result is lower-cased. This
362	     * is how both {@code lastName} and {@code address} are compared so that differences of case or
363	     * spacing do not defeat the duplicate-household check.
364	     */
365	    private static String collapse(String value) {
366	        return value == null ? "" : value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
367	    }
368	
369	    /**
370	     * Normalizes an owner's address into a canonical form applied on every create: leading and
371	     * trailing whitespace is trimmed, any internal run of whitespace is reduced to a single space,
372	     * the value is upper-cased, and common street-type abbreviations are expanded on a per-word
373	     * basis ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). The result is stored
374	     * and returned, and is the form every address comparison (duplicate-household detection and the
375	     * shared {@code householdId}) uses. A {@code null} or whitespace-only input normalizes to the
376	     * empty string, which the required-field guard then rejects. The transformation is idempotent,
377	     * so normalizing an already-normalized address is a no-op.
378	     */
379	    private static String normalizeAddress(String address) {
380	        if (address == null) {
381	            return "";
382	        }
383	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
384	        if (collapsed.isEmpty()) {
385	            return "";
386	        }
387	        String[] tokens = collapsed.split(" ");
388	        StringBuilder sb = new StringBuilder(collapsed.length());
389	        for (int i = 0; i < tokens.length; i++) {
390	            String token = tokens[i];
391	            switch (token) {
392	                case "ST" -> token = "STREET";
393	                case "RD" -> token = "ROAD";
394	                case "AVE" -> token = "AVENUE";
395	                default -> {
396	                }
397	            }
398	            if (i > 0) {
399	                sb.append(' ');
400	            }
401	            sb.append(token);
402	        }
403	        return sb.toString();
404	    }
405	
406	    /**
407	     * Derives an owner's region code from its postcode, falling back to its city. A present postcode
408	     * that falls in a known region's inclusive 4-digit range wins (NSW 2000-2099, VIC 3000-3099, QLD
409	     * 4000-4099); otherwise the fixed city-to-region table is consulted (Sydney -> NSW, Melbourne ->
410	     * VIC, Brisbane -> QLD); a value resolved by neither is {@code "UNKNOWN"}. This is the single
411	     * region derivation shared by the {@code customerCode} and the owner's locality.
412	     */
413	    private static String deriveRegion(String city, String postcode) {
414	        if (postcode != null) {
415	            try {
416	                int pc = Integer.parseInt(postcode.trim());
417	                for (Map.Entry<String, int[]> range : REGION_POSTCODES.entrySet()) {
418	                    int[] bounds = range.getValue();
419	                    if (pc >= bounds[0] && pc <= bounds[1]) {
420	                        return range.getKey();
421	                    }
422	                }
423	            } catch (NumberFormatException ignored) {
424	                // not a numeric postcode; fall back to the city-to-region table
425	            }
426	        }
427	        return CITY_REGION.getOrDefault(city, "UNKNOWN");
428	    }
429	
430	    /**
431	     * Builds the {@code customerCode} for a newly created owner, formatted {@code '<REGION>-<HASH8>'}
432	     * where {@code REGION} is the region code derived from the owner's postcode (falling back to its
433	     * city) and {@code HASH8} is the first 8 upper-case hex characters of SHA-256 over
434	     * {@code normalizedTelephone + lastName} (e.g. {@code 'NSW-1A2B3C4D'}). This is a stable identity:
435	     * it carries no sequence number and depends only on the owner's own region, telephone and surname.
436	     */
437	    private static String customerCodeFor(String region, String normalizedTelephone, String lastName) {
438	        return region + "-" + sha256HexPrefix(normalizedTelephone + lastName, 8);
439	    }
440	
441	    /**
442	     * De-duplicates a freshly computed {@code customerCode} against the codes already carried by
443	     * existing owners. When the base code is unused it is returned unchanged; otherwise
444	     * {@code '-<n>'} is appended with the smallest {@code n} of 2 or more that yields a code no
445	     * existing owner already holds. The count reflects the state prior to this create.
446	     */
447	    private String deduplicateCustomerCode(String baseCode) {
448	        Set<String> existingCodes = new HashSet<>();
449	        for (Owner existing : this.clinicService.findAllOwners()) {
450	            String code = existing.getCustomerCode();
451	            if (code != null) {
452	                existingCodes.add(code);
453	            }
454	        }
455	        if (!existingCodes.contains(baseCode)) {
456	            return baseCode;
457	        }
458	        int n = 2;
459	        while (existingCodes.contains(baseCode + "-" + n)) {
460	            n++;
461	        }
462	        return baseCode + "-" + n;
463	    }
464	
465	    /**
466	     * Returns the first {@code hexChars} upper-case hex characters of the SHA-256 digest of the UTF-8
467	     * bytes of {@code value}.
468	     */
469	    private static String sha256HexPrefix(String value, int hexChars) {
470	        try {
471	            byte[] digest = MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8));
472	            StringBuilder sb = new StringBuilder(hexChars);
473	            for (byte b : digest) {
474	                if (sb.length() >= hexChars) {
475	                    break;
476	                }
477	                sb.append(String.format("%02X", b));
478	            }
479	            return sb.substring(0, hexChars);
480	        } catch (NoSuchAlgorithmException ex) {
481	            throw new IllegalStateException("SHA-256 not available", ex);
482	        }
483	    }
484	
485	    /**
486	     * Builds the {@code membershipNumber} for a newly created owner, formatted
487	     * {@code '<customerCode>-M<YY>'} where {@code YY} is the last two digits of the
488	     * fiscal year of the {@code registrationDate} (e.g. {@code 'SMI-0007-M27'}). The year
489	     * segment therefore matches the owner's {@code fiscalYear}.
490	     */
491	    private static String membershipNumberFor(String customerCode, LocalDate registrationDate) {
492	        return String.format("%s-M%02d", customerCode, fiscalYearOf(registrationDate) % 100);
493	    }
494	
495	    /**
496	     * The fiscal year, as a four-digit year, of a business-day-adjusted date. The fiscal year
497	     * starts on 1 July and is labelled by the calendar year in which it ends: a date on or after
498	     * 1 July belongs to the fiscal year ending the following calendar year, while an earlier date
499	     * belongs to the fiscal year ending in its own year.
500	     */
501	    private static int fiscalYearOf(LocalDate date) {
502	        return date.getMonthValue() >= Month.JULY.getValue() ? date.getYear() + 1 : date.getYear();
503	    }
504	
505	    /**
506	     * Derives the stable {@code householdId} for an owner from the collapsed {@code lastName} and
507	     * its {@code postcode} - the same pair used to detect a shared household. It is the first 12
508	     * lower-case hex characters of SHA-256 over {@code normalizedLastName + '|' + postcode}. Because
509	     * it is a pure function of that pair, every owner in the same household - whether created first
510	     * or joining later via {@code sharesHousehold} - receives the identical, non-blank identifier
511	     * without needing to read any other owner's value. A {@code null} postcode contributes an empty
512	     * segment.
513	     */
514	    private static String householdIdFor(String lastName, String postcode) {
515	        String key = collapse(lastName) + "|" + (postcode == null ? "" : postcode);
516	        try {
517	            byte[] digest = MessageDigest.getInstance("SHA-256").digest(key.getBytes(StandardCharsets.UTF_8));
518	            StringBuilder sb = new StringBuilder(12);
519	            for (byte b : digest) {
520	                if (sb.length() >= 12) {
521	                    break;
522	                }
523	                sb.append(String.format("%02x", b));
524	            }
525	            return sb.substring(0, 12);
526	        } catch (NoSuchAlgorithmException ex) {
527	            throw new IllegalStateException("SHA-256 not available", ex);
528	        }
529	    }
530	
531	    /**
532	     * Counts the existing owners who already share the given {@code firstName} and {@code lastName},
533	     * compared case-insensitively. This is evaluated before the new owner is saved, so it reflects
534	     * the state prior to this create and is stored on the owner as its {@code namesakeCount}.
535	     */
536	    private int countNamesakes(String firstName, String lastName) {
537	        int count = 0;
538	        for (Owner existing : this.clinicService.findAllOwners()) {
539	            if (firstName.equalsIgnoreCase(existing.getFirstName())
540	                && lastName.equalsIgnoreCase(existing.getLastName())) {
541	                count++;
542	            }
543	        }
544	        return count;
545	    }
546	
547	    /**
548	     * Counts the members of the household the new owner will belong to, as it stands after this
549	     * create. Every existing owner carrying the same {@code householdId} is counted, and the new
550	     * owner itself is added, so a value of 3 or more means the owner joins a household of at least
551	     * three members. This is evaluated with the new owner's {@code householdId} already set and is
552	     * stored on the owner as its {@code householdMemberCount}.
553	     */
554	    private int countHouseholdMembers(String householdId) {
555	        int count = 1;
556	        for (Owner existing : this.clinicService.findAllOwners()) {
557	            if (householdId.equals(existing.getHouseholdId())) {
558	                count++;
559	            }
560	        }
561	        return count;
562	    }
563	
564	    /**
565	     * Finds an existing owner that makes the new owner a <em>possible</em> (soft) duplicate: one
566	     * that is not a hard identity collision but shares the new owner's {@code lastName} (compared
567	     * case-insensitively) and {@code postcode} while carrying a different normalized telephone. The
568	     * new owner's postcode must be present for a soft match to be possible. When several existing
569	     * owners qualify the one with the lowest id is chosen. Returns the matching owner's id, or
570	     * {@code null} when there is no soft match. This is evaluated after the hard-duplicate check has
571	     * already passed, so any owner sharing the lastName and postcode necessarily differs in telephone.
572	     *
573	     * <p>Because the household is now keyed on {@code (lastName, postcode)} - exactly the soft-match
574	     * key - a co-member reached here can only be one the caller declared via {@code sharesHousehold}
575	     * (otherwise the hard household-duplicate check would already have rejected it). A declared
576	     * household member is not a suspected duplicate, so no soft match is reported in that case.
577	     */
578	    private Integer findPossibleDuplicateOf(OwnerFieldsDto ownerFieldsDto, String normalizedTelephone) {
579	        if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
580	            return null;
581	        }
582	        String postcode = ownerFieldsDto.getPostcode();
583	        if (postcode == null) {
584	            return null;
585	        }
586	        String lastName = ownerFieldsDto.getLastName();
587	        Integer matchId = null;
588	        for (Owner existing : this.clinicService.findAllOwners()) {
589	            if (existing.isDeleted()) {
590	                continue;
591	            }
592	            if (lastName == null || !lastName.equalsIgnoreCase(existing.getLastName())) {
593	                continue;
594	            }
595	            if (!postcode.equals(existing.getPostcode())) {
596	                continue;
597	            }
598	            String existingTelephone;
599	            try {
600	                existingTelephone = normalizeTelephone(existing.getTelephone());
601	            } catch (InvalidTelephoneException ex) {
602	                existingTelephone = null;
603	            }
604	            if (normalizedTelephone.equals(existingTelephone)) {
605	                continue;
606	            }
607	            if (existing.getId() != null && (matchId == null || existing.getId() < matchId)) {
608	                matchId = existing.getId();
609	            }
610	        }
611	        return matchId;
612	    }
613	
614	    /**
615	     * The tenure, in elapsed fiscal years, that an owner must exceed before its tenure contributes
616	     * membership points. Tenure is measured from the owner's {@code registrationDate}, so a newly
617	     * created owner (whose tenure is zero) never satisfies this and thus never earns the tenure
618	     * points on create.
619	     */
620	    private static final int TENURE_POINTS_THRESHOLD_FISCAL_YEARS = 1;
621	
622	    /**
623	     * The household size (number of members) at or above which an owner earns the household points.
624	     */
625	    private static final int HOUSEHOLD_POINTS_THRESHOLD = 3;
626	
627	    /**
628	     * Computes the {@code membershipPoints} for an owner. Points start at 0, gain 2 when an email is
629	     * present, gain 1 when the owner's {@code namesakeCount} is 0, gain 2 when the owner's household
630	     * has {@value #HOUSEHOLD_POINTS_THRESHOLD} or more members, and gain 3 when the owner's tenure
631	     * (elapsed fiscal years since its {@code registrationDate}) exceeds
632	     * {@value #TENURE_POINTS_THRESHOLD_FISCAL_YEARS}. Because a newly created owner has zero tenure,
633	     * the tenure points never apply on create.
634	     * Evaluated after the owner's email, namesakeCount, householdMemberCount and registrationDate
635	     * have been set.
636	     */
637	    private static int membershipPointsFor(Owner owner) {
638	        int points = 0;
639	        if (owner.getEmail() != null && !owner.getEmail().isEmpty()) {
640	            points += 2;
641	        }
642	        if (owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0) {
643	            points += 1;
644	        }
645	        if (owner.getHouseholdMemberCount() != null
646	            && owner.getHouseholdMemberCount() >= HOUSEHOLD_POINTS_THRESHOLD) {
647	            points += 2;
648	        }
649	        if (tenureInFiscalYears(owner) > TENURE_POINTS_THRESHOLD_FISCAL_YEARS) {
650	            points += 3;
651	        }
652	        return points;
653	    }
654	
655	    /**
656	     * Maps {@code membershipPoints} to the numeric {@code membershipLevel}: level 1 for 0-1 points,
657	     * 2 for 2-3, 3 for 4-5, and 4 for 6 or more points.
658	     */
659	    private static int membershipLevelForPoints(int points) {
660	        if (points <= 1) {
661	            return 1;
662	        }
663	        if (points <= 3) {
664	            return 2;
665	        }
666	        if (points <= 5) {
667	            return 3;
668	        }
669	        return 4;
670	    }
671	
672	    /**
673	     * The owner's tenure in whole elapsed fiscal years: the number of 1 July fiscal-year boundaries
674	     * crossed between its {@code registrationDate} and the current server date. An owner with no
675	     * registration date, or one dated in the future, has a tenure of zero.
676	     */
677	    private static long tenureInFiscalYears(Owner owner) {
678	        LocalDate registrationDate = owner.getRegistrationDate();
679	        if (registrationDate == null) {
680	            return 0;
681	        }
682	        return Math.max(0, fiscalYearOf(LocalDate.now()) - fiscalYearOf(registrationDate));
683	    }
684	
685	    /**
686	     * The maximum number of owners any single city may contain. A create whose city already
687	     * holds this many owners is rejected.
688	     */
689	    private static final int CITY_CAPACITY = 50;
690	
691	    /**
692	     * Rejects a create whose city already contains {@value #CITY_CAPACITY} or more owners,
693	     * compared case-insensitively - the same way the city is matched when building the
694	     * {@code customerCode} sequence. The count reflects the state prior to this create. A city
695	     * at capacity is reported via {@link CityAtCapacityException}, which the exception handler
696	     * translates to a 409.
697	     */
698	    private void rejectCityAtCapacity(String city) {
699	        int count = 0;
700	        for (Owner existing : this.clinicService.findAllOwners()) {
701	            if (city.equalsIgnoreCase(existing.getCity())) {
702	                count++;
703	            }
704	        }
705	        if (count >= CITY_CAPACITY) {
706	            throw new CityAtCapacityException(city);
707	        }
708	    }
709	
710	    /**
711	     * The maximum number of owners that may be created on any single day (by
712	     * {@code registrationDate}). A create attempted once this many owners already carry the
713	     * current day's registration date is rejected.
714	     */
715	    private static final int DAILY_OWNER_LIMIT = 100;
716	
717	    /**
718	     * Rejects a create once {@value #DAILY_OWNER_LIMIT} or more owners already carry the given
719	     * business-day-adjusted {@code registrationDate} (the date the new owner will itself receive).
720	     * The count reflects the state prior to this create. When the limit is reached the create is
721	     * reported via {@link DailyOwnerLimitExceededException}, which the exception handler translates
722	     * to a 429 Too Many Requests.
723	     */
724	    private void rejectDailyOwnerLimit(LocalDate registrationDate) {
725	        int count = 0;
726	        for (Owner existing : this.clinicService.findAllOwners()) {
727	            if (registrationDate.equals(existing.getRegistrationDate())) {
728	                count++;
729	            }
730	        }
731	        if (count >= DAILY_OWNER_LIMIT) {
732	            throw new DailyOwnerLimitExceededException();
733	        }
734	    }
735	
736	    /**
737	     * The number of owners that must already carry a given {@code registrationDate} before a
738	     * create on that date is flagged with a bulk-signup warning. Once <em>more than</em> this
739	     * many owners already exist for the day, the new owner's {@code bulkSignupWarning} is true.
740	     */
741	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
742	
743	    /**
744	     * Computes the {@code bulkSignupWarning} for a create on the given business-day-adjusted
745	     * {@code registrationDate}: true when more than {@value #BULK_SIGNUP_WARNING_THRESHOLD} owners
746	     * have already been created for that date, otherwise false. The count reflects the state prior
747	     * to this create, matching how the daily-limit rule accumulates.
748	     */
749	    private boolean bulkSignupWarningFor(LocalDate registrationDate) {
750	        int count = 0;
751	        for (Owner existing : this.clinicService.findAllOwners()) {
752	            if (registrationDate.equals(existing.getRegistrationDate())) {
753	                count++;
754	            }
755	        }
756	        return count > BULK_SIGNUP_WARNING_THRESHOLD;
757	    }
758	
759	    /**
760	     * Rolls an effective registration date forward onto a business day. A Saturday, Sunday or listed
761	     * public holiday is advanced to the next non-holiday business day; a plain weekday is returned
762	     * unchanged. This is applied to the effective registration date - whether supplied in the request
763	     * or defaulted to the server date - so the stored {@code registrationDate}, and everything derived
764	     * from it, always falls on a business day.
765	     */
766	    /**
767	     * Rejects a supplied {@code registrationDate} that lies in the future. A registration date is
768	     * only ever explicitly supplied on the request; when present it must not be later than the
769	     * current server date. A future date raises a {@link FutureRegistrationDateException}, which the
770	     * exception handler translates to a 400 Bad Request. A {@code null} date (the default, filled in
771	     * later from the server date) is accepted.
772	     */
773	    private static void rejectFutureRegistrationDate(LocalDate registrationDate) {
774	        if (registrationDate != null && registrationDate.isAfter(LocalDate.now())) {
775	            throw new FutureRegistrationDateException(registrationDate);
776	        }
777	    }
778	
779	    /**
780	     * The fixed list of public holidays. An effective registration date that lands on any of these
781	     * is rolled forward, together with weekends, to the next non-holiday business day.
782	     */
783	    private static final Set<LocalDate> PUBLIC_HOLIDAYS = Set.of(
784	        LocalDate.of(2026, 1, 1),
785	        LocalDate.of(2026, 1, 26),
786	        LocalDate.of(2026, 4, 25),
787	        LocalDate.of(2026, 12, 25),
788	        LocalDate.of(2026, 12, 28));
789	
790	    private static LocalDate toBusinessDay(LocalDate date) {
791	        while (isWeekend(date) || PUBLIC_HOLIDAYS.contains(date)) {
792	            date = date.plusDays(1);
793	        }
794	        return date;
795	    }
796	
797	    private static boolean isWeekend(LocalDate date) {
798	        return switch (date.getDayOfWeek()) {
799	            case SATURDAY, SUNDAY -> true;
800	            default -> false;
801	        };
802	    }
803	
804	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
805	    @Override
806	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
807	        String normalizedLine1 = null;
808	        String normalizedLine2 = null;
809	        String composedAddress;
810	        if (!isBlank(ownerFieldsDto.getAddressLine1())) {
811	            normalizedLine1 = normalizeAddress(ownerFieldsDto.getAddressLine1());
812	            if (!isBlank(ownerFieldsDto.getAddressLine2())) {
813	                normalizedLine2 = normalizeAddress(ownerFieldsDto.getAddressLine2());
814	            }
815	            composedAddress = normalizedLine2 == null
816	                ? normalizedLine1
817	                : normalizedLine1 + " " + normalizedLine2;
818	        } else {
819	            composedAddress = normalizeAddress(ownerFieldsDto.getAddress());
820	        }
821	        rejectMissingOrBlankFields(ownerFieldsDto, composedAddress);
822	        rejectCityAtCapacity(ownerFieldsDto.getCity());
823	        HttpHeaders headers = new HttpHeaders();
824	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
825	        owner.setAddress(composedAddress);
826	        owner.setAddressLine1(normalizedLine1);
827	        owner.setAddressLine2(normalizedLine2);
828	        String normalizedTelephone = normalizeTelephone(ownerFieldsDto.getTelephone());
829	        owner.setTelephone(normalizedTelephone);
830	        String normalizedEmail = normalizeEmail(ownerFieldsDto.getEmail());
831	        owner.setEmail(normalizedEmail);
832	        validatePostcode(owner.getCity(), owner.getPostcode());
833	        String householdId = householdIdFor(owner.getLastName(), owner.getPostcode());
834	        rejectDuplicateIdentity(ownerFieldsDto, normalizedTelephone, normalizedEmail, householdId);
835	        rejectFutureRegistrationDate(owner.getRegistrationDate());
836	        LocalDate effectiveDate = owner.getRegistrationDate() == null ? LocalDate.now() : owner.getRegistrationDate();
837	        LocalDate registrationDate = toBusinessDay(effectiveDate);
838	        rejectDailyOwnerLimit(registrationDate);
839	        owner.setBulkSignupWarning(bulkSignupWarningFor(registrationDate));
840	        owner.setRegistrationDate(registrationDate);
841	        String region = deriveRegion(owner.getCity(), owner.getPostcode());
842	        owner.setCustomerCode(deduplicateCustomerCode(customerCodeFor(region, normalizedTelephone, owner.getLastName())));
843	        owner.setMembershipNumber(membershipNumberFor(owner.getCustomerCode(), owner.getRegistrationDate()));
844	        owner.setHouseholdId(householdId);
845	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
846	        owner.setHouseholdMemberCount(countHouseholdMembers(owner.getHouseholdId()));
847	        int membershipPoints = membershipPointsFor(owner);
848	        owner.setMembershipPoints(membershipPoints);
849	        owner.setMembershipLevel(membershipLevelForPoints(membershipPoints));
850	        Integer possibleDuplicateOf = findPossibleDuplicateOf(ownerFieldsDto, normalizedTelephone);
851	        owner.setPossibleDuplicate(possibleDuplicateOf != null);
852	        owner.setPossibleDuplicateOf(possibleDuplicateOf);
853	        this.clinicService.saveOwner(owner);
854	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
855	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(), owner.getMembershipLevel(), owner.getMembershipNumber());
856	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
857	        headers.setLocation(UriComponentsBuilder.newInstance()
858	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
859	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
860	    }
861	
862	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
863	    @Override
864	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
865	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
866	        if (currentOwner == null) {
867	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
868	        }
869	        currentOwner.setAddress(ownerFieldsDto.getAddress());
870	        currentOwner.setCity(ownerFieldsDto.getCity());
871	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
872	        currentOwner.setLastName(ownerFieldsDto.getLastName());
873	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
874	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
875	        this.clinicService.saveOwner(currentOwner);
876	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
877	    }
878	
879	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
880	    @Transactional
881	    @Override
882	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
883	        Owner owner = this.clinicService.findOwnerById(ownerId);
884	        if (owner == null) {
885	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
886	        }
887	        owner.setDeleted(true);
888	        this.clinicService.saveOwner(owner);
889	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
890	    }
891	
892	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
893	    @Override
894	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
895	        Owner owner = this.clinicService.findOwnerById(ownerId);
896	        if (owner == null) {
897	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
898	        }
899	        HttpHeaders headers = new HttpHeaders();
900	        Pet pet = petMapper.toPet(petFieldsDto);
901	        owner.setId(ownerId);
902	        pet.setOwner(owner);
903	        pet.getType().setName(null);
904	        this.clinicService.savePet(pet);
905	        PetDto petDto = petMapper.toPetDto(pet);
906	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
907	            .buildAndExpand(pet.getId()).toUri());
908	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
909	    }
910	
911	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
912	    @Override
913	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
914	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
915	        if (currentOwner != null) {
916	            Pet currentPet = this.clinicService.findPetById(petId);
917	            if (currentPet != null) {
918	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
919	                currentPet.setName(petFieldsDto.getName());
920	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
921	                this.clinicService.savePet(currentPet);
922	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
923	            }
924	        }
925	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
926	    }
927	
928	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
929	    @Override
930	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
931	        HttpHeaders headers = new HttpHeaders();
932	        Visit visit = visitMapper.toVisit(visitFieldsDto);
933	        Pet pet = new Pet();
934	        pet.setId(petId);
935	        visit.setPet(pet);
936	        this.clinicService.saveVisit(visit);
937	        VisitDto visitDto = visitMapper.toVisitDto(visit);
938	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
939	            .buildAndExpand(visit.getId()).toUri());
940	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
941	    }
942	
943	
944	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
945	    @Override
946	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
947	        Owner owner = this.clinicService.findOwnerById(ownerId);
948	        if (owner != null) {
949	            Pet pet = owner.getPet(petId);
950	            if (pet != null) {
951	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
952	            }
953	        }
954	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
955	    }
